var t=[{title:`Waarom gewoonten ertoe doen`,text:`Kracht, cardiovasculaire capaciteit en bewegingsvaardigheid ontwikkelen zich door herhaalde oefening. Een training die op papier geweldig lijkt, is nutteloos als hij te lang, onhandig of onprettig is om te herhalen. Daardoor horen frequentie en volhouden bij het schema-ontwerp, en zijn ze niet alleen een kwestie van motivatie.`},{title:`Koppel training aan een aanleiding`,text:`Koppel training aan iets wat al gebeurt of aan een vaste afspraak: „Na het werk op maandag en donderdag doe ik mijn sessie van 25 minuten.” Leg je kleding, ruimte of uitrusting vooraf klaar. Maak de eerste stap piepklein, zoals je schoenen aandoen en een warming-up van vijf minuten beginnen, zodat je niet van enthousiasme afhankelijk bent.`},{title:`Heb een minimale sessie`,text:`Op een drukke dag kunnen één squatvariant, één duw- of trekoefening en een korte wandeling de gewoonte in leven houden. De minimale sessie is geen blijvende vervanging voor progressieve training. Het doel is te voorkomen dat één gemiste dag verandert in meerdere gemiste weken. Noteer wat je echt hebt gedaan, en log een verkorte training niet als voltooid.`},{title:`Ga rustig om met tegenslagen`,text:`Een gemiste sessie wist je eerdere aanpassingen niet uit. Pak de volgende geplande training weer op en verdubbel de belasting niet om gemiste training „terug te betalen”. Verlaag na ziekte, ernstige vermoeidheid of een lange pauze de intensiteit en het volume tot je gebruikelijke tolerantie terugkeert.`},{title:`Check je omgeving`,text:`Slechte slaap, een gedoe om naar de sportschool te gaan, uitrusting waar je niet bij kunt en te lange sessies kunnen allemaal de consistentie ondermijnen. Dit oplossen kan meer helpen dan een nieuwe oefening zoeken. Plezier in je training en het zelf kiezen ervan maken een routine ook makkelijker vol te houden.`},{title:`TrainUp gebruiken`,text:`Stel in Profiel een realistisch aantal trainingsdagen en je voorkeursdagen in, en vul je ruimte en uitrusting in zodat het schema alleen oefeningen kiest die passen. Trainingsherinneringen op het Dashboard kunnen je aanleiding zijn. Geschiedenis toont de trainingen van deze week en je totaal, en vooruitgang telt over veel weken, dus je hebt geen perfecte reeks nodig.`}];var i=[{label:`CDC: beweeggewoonten en planning`,url:`https://www.cdc.gov/healthy-weight-growth/physical-activity/getting-started.html`},{label:`Beweegaanbevelingen van de WHO`,url:`https://www.who.int/europe/news-room/fact-sheets/item/physical-activity`}];var a={sections:t,sources:i};export{a as default,t as sections,i as sources};